if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api GET "/networks/$NETWORK_ID/appliance/firewall/portForwardingRules" > "$OUT/before-portForwardingRules.json"
api GET "/networks/$NETWORK_ID/appliance/firewall/oneToOneNatRules" > "$OUT/before-oneToOneNatRules.json"
api GET "/networks/$NETWORK_ID/appliance/firewall/oneToManyNatRules" > "$OUT/before-oneToManyNatRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
api PUT "/networks/$NETWORK_ID/appliance/firewall/portForwardingRules" "$OUT/portForwardingRules.json" > "$OUT/after-portForwardingRules.json"
sleep 0.2
api PUT "/networks/$NETWORK_ID/appliance/firewall/oneToOneNatRules" "$OUT/oneToOneNatRules.json" > "$OUT/after-oneToOneNatRules.json"
sleep 0.2
api PUT "/networks/$NETWORK_ID/appliance/firewall/oneToManyNatRules" "$OUT/oneToManyNatRules.json" > "$OUT/after-oneToManyNatRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
